(function(){
  function hexA(hex,a){
    const r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
    return 'rgba('+r+','+g+','+b+','+a+')';
  }
  const particles=[];
  const N=80;
  for(let i=0;i<N;i++){
    particles.push({x:Math.random()*W(), y:Math.random()*H(), r:1.5+Math.random()*4, spd:0.12+Math.random()*0.3, ph:Math.random()*Math.PI*2, amp:8+Math.random()*26, hue:Math.random()});
  }
  const bearFx=0.78, bearFy=0.72;
  function drawPlushLoop(x,y,r,rot,color){
    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(rot);
    ctx.strokeStyle=color;
    ctx.lineWidth=1.4;
    ctx.beginPath();
    ctx.arc(0,0,r,0,Math.PI*1.5);
    ctx.stroke();
    ctx.restore();
  }
  function drawBear(t){
    const w=W(), h=H();
    const cx=w*bearFx, cy=h*bearFy;
    const scale=Math.min(w,h)*0.22;
    ctx.save();
    ctx.translate(cx,cy);
    const wob=Math.sin(t*0.0006)*0.02;
    ctx.rotate(wob);
    ctx.globalAlpha=0.9;
    const parts=[
      {x:0,y:0.3*scale,r:0.9*scale},
      {x:0,y:-0.55*scale,r:0.55*scale},
      {x:-0.45*scale,y:-0.95*scale,r:0.22*scale},
      {x:0.45*scale,y:-0.95*scale,r:0.22*scale},
      {x:-0.85*scale,y:0.15*scale,r:0.32*scale},
      {x:0.85*scale,y:0.15*scale,r:0.32*scale},
      {x:-0.4*scale,y:0.95*scale,r:0.35*scale},
      {x:0.4*scale,y:0.95*scale,r:0.35*scale}
    ];
    const colDark=PALETTE[2];
    parts.forEach(function(p,i){
      const grad=ctx.createRadialGradient(p.x-p.r*0.3,p.y-p.r*0.3,p.r*0.1,p.x,p.y,p.r);
      grad.addColorStop(0, hexA(PALETTE[1],0.55));
      grad.addColorStop(1, hexA(PALETTE[0],0.35));
      ctx.beginPath();
      ctx.fillStyle=grad;
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fill();
      const loops=8;
      for(let j=0;j<loops;j++){
        const a=(j/loops)*Math.PI*2 + t*0.0002*(i%2===0?1:-1);
        const lx=p.x+Math.cos(a)*p.r*0.95;
        const ly=p.y+Math.sin(a)*p.r*0.95;
        drawPlushLoop(lx,ly,p.r*0.14,a,hexA(colDark,0.5));
      }
    });
    ctx.beginPath();
    ctx.fillStyle=hexA(PALETTE[2],0.6);
    ctx.ellipse(0,-0.45*scale, scale*0.16, scale*0.11, 0,0,Math.PI*2);
    ctx.fill();
    ctx.restore();
  }
  function frame(t){
    const w=W(), h=H();
    const cg=ctx.createRadialGradient(w*0.5,h*0.48,0,w*0.5,h*0.48,Math.max(w,h)*0.5);
    cg.addColorStop(0, hexA(PALETTE[1],0.10));
    cg.addColorStop(1, hexA(PALETTE[1],0));
    ctx.fillStyle=cg;
    ctx.fillRect(0,0,w,h);
    particles.forEach(function(p){
      p.y -= p.spd;
      if(p.y < -10){ p.y = h+10; p.x = Math.random()*w; }
      const dx = Math.sin(t*0.0007 + p.ph)*p.amp*0.3;
      const x = p.x+dx, y = p.y;
      const col = p.hue<0.33?PALETTE[0]:(p.hue<0.66?PALETTE[1]:PALETTE[2]);
      ctx.save();
      ctx.globalAlpha=0.5;
      ctx.shadowColor=hexA(col,0.6);
      ctx.shadowBlur=8;
      ctx.beginPath();
      ctx.fillStyle=hexA(col,0.55);
      ctx.arc(x,y,p.r,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    });
    drawBear(t);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
